const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let matchType='alle',locationType='alle',expanded=false;
const months=['jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec'];
const monthNames=['januari','februari','maart','april','mei','juni','juli','augustus','september','oktober','november','december'];
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Brussels',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function formatChecked(iso){const [year,month,day]=iso.split('-');return `${Number(day)} ${monthNames[Number(month)-1]} ${year}`}
function scoreOf(f){return f.score&&Number.isFinite(f.score.home)&&Number.isFinite(f.score.away)?f.score:null}
function scoreLabel(s){return `${s.home} – ${s.away}`}
function ourResult(f){const s=scoreOf(f);if(!s)return '';const ours=f.home==='De Zwaluw'?s.home:s.away;const theirs=f.home==='De Zwaluw'?s.away:s.home;return ours>theirs?'win':ours<theirs?'loss':'draw'}
function renderFixtures(){
 const filtered=clubData.fixtures.filter(f=>(matchType==='alle'||f.type===matchType)&&(locationType==='alle'||(locationType==='thuis')===(f.home==='De Zwaluw')));
 const visible=expanded?filtered:filtered.slice(0,6);
 document.querySelector('#fixtures').innerHTML=visible.map(f=>{const [year,month,day]=f.date.split('-');const home=f.home==='De Zwaluw';const maps='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(f.address);const score=scoreOf(f);const result=ourResult(f);const middle=score?`<span class="score score-${result}">${scoreLabel(score)}</span>`:'<span class="vs">vs</span>';const note=score?`Uitslag ${scoreLabel(score)} · Uur niet vermeld · Volgens ATC-wedstrijdblad.`:`Uur niet vermeld · Nog geen uitslag bij controle op ${formatChecked(clubData.checked)}.`;return `<details class="fixture${score?' played':''}"><summary><time class="fixture-date" datetime="${f.date}"><strong>${day}</strong><span>${months[Number(month)-1]} ${year}</span></time><div><div class="fixture-teams"><span class="${home?'ours':''}">${escapeHTML(f.home)}</span>${middle}<span class="${!home?'ours':''}">${escapeHTML(f.away)}</span></div><div class="fixture-meta"><span class="${f.type==='beker'?'cup-tag':'competition'}">${f.type==='beker'?'BEKER VAN ATC':'COMPETITIE · 1A'}</span><span>·</span><span>${home?'THUIS':'UIT'}</span></div></div><div class="venue">${escapeHTML(f.venue)}<small>${score?scoreLabel(score):'Uur niet vermeld'}</small></div><span class="fixture-toggle" aria-hidden="true">＋</span></summary><div class="fixture-detail"><p><strong>${escapeHTML(f.venue)}</strong><br>${escapeHTML(f.address)}<br>${note}</p><div class="fixture-links"><a href="${maps}" target="_blank" rel="noopener">Route ↗</a><a href="${f.url}" target="_blank" rel="noopener">Wedstrijdblad ATC ↗</a></div></div></details>`}).join('')||'<p class="empty">Geen wedstrijden voor deze selectie. Kies een andere speelplaats of wedstrijdsoort.</p>';
 document.querySelector('#result-count').textContent=`${visible.length} van ${filtered.length} ${filtered.length===1?'wedstrijd':'wedstrijden'} · Seizoen 2026–2027`;
 const more=document.querySelector('#show-more');more.hidden=filtered.length<=6;more.style.display=filtered.length<=6?'none':'';more.innerHTML=expanded?'Minder wedstrijden <span>−</span>':'Volledige kalender <span>＋</span>';more.setAttribute('aria-expanded',String(expanded));
}
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{matchType=button.dataset.type;expanded=false;document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});renderFixtures()}));
document.querySelector('#location').addEventListener('change',event=>{locationType=event.target.value;expanded=false;renderFixtures()});
document.querySelector('#show-more').addEventListener('click',()=>{expanded=!expanded;renderFixtures()});
renderFixtures();
document.querySelectorAll('.cup-match').forEach(card=>{const fixture=clubData.fixtures.find(f=>f.url===card.href);const score=fixture&&scoreOf(fixture);if(!score)return;const heading=card.querySelector('h3');if(heading)heading.innerHTML=`${escapeHTML(fixture.home)} <span class="cup-score score-${ourResult(fixture)}">${scoreLabel(score)}</span> ${escapeHTML(fixture.away)}`});
const snapshot=document.querySelector('.snapshot');if(snapshot)snapshot.textContent=`Kalenderstand: ${formatChecked(clubData.checked)} · Aanvangsuren zijn niet vermeld door ATC.`;
const next=clubData.fixtures.find(f=>!scoreOf(f)&&f.date>=today)||clubData.fixtures.find(f=>f.date>=today);
if(next){const [year,month,day]=next.date.split('-');document.querySelector('.match-label p').innerHTML=(next.type==='beker'?'BEKER VAN ATC':'COMPETITIE · 1A')+' <span>'+(next.home==='De Zwaluw'?'THUIS':'UIT')+'</span>';document.querySelector('.next-teams').innerHTML=`${next.home==='De Zwaluw'?'<strong>De Zwaluw</strong>':escapeHTML(next.home)} <span>vs</span> ${next.away==='De Zwaluw'?'<strong>De Zwaluw</strong>':escapeHTML(next.away)}`;document.querySelector('.next-date').innerHTML=`<strong>${day} ${months[Number(month)-1].toUpperCase()}</strong><span>Vrijdag · ${year}</span>`;const nextLink=document.querySelector('.next-match .round-link');nextLink.href=next.url;nextLink.setAttribute('aria-label',`${next.home} tegen ${next.away} op ATC`)}else{document.querySelector('.next-match').innerHTML='<div><p class="eyebrow">SEIZOEN 2026–2027</p><p>Geen latere bevestigde wedstrijd in deze kalender. <a class="text-link" href="https://www.atc-tafelvoetbal.be/clubs/186" target="_blank" rel="noopener">Bekijk ATC voor nieuwe data ↗</a></p></div>'}
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let motionEnabled=!reduced.matches;
const motionButton=document.createElement('button');motionButton.className='motion-control';document.querySelector('footer').append(motionButton);
function motionState(){document.documentElement.classList.toggle('no-motion',!motionEnabled);motionButton.textContent=motionEnabled?'Beweging aan':'Beweging uit';motionButton.setAttribute('aria-label',motionEnabled?'Animaties uitschakelen':'Animaties inschakelen');motionButton.setAttribute('aria-pressed',String(motionEnabled))}motionState();motionButton.addEventListener('click',()=>{motionEnabled=!motionEnabled;motionState()});reduced.addEventListener('change',e=>{motionEnabled=!e.matches;motionState()});
const hero=document.querySelector('.hero'),bird=document.querySelector('.hero-art img');
hero.addEventListener('pointermove',e=>{if(!motionEnabled||e.pointerType!=='mouse')return;const rect=hero.getBoundingClientRect();const x=(e.clientX-rect.left)/rect.width-.5,y=(e.clientY-rect.top)/rect.height-.5;bird.style.transform=`translate(${x*26}px,${y*22}px) rotate(${x*1.8}deg) scale(1.015)`});hero.addEventListener('pointerleave',()=>{bird.style.transform='none'});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){if(motionEnabled)entry.target.classList.add('reveal');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.section-title,.cup-intro,.cup-fixtures,.standings-intro,.team-heading,.home-name,.home-address').forEach(el=>observer.observe(el));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}});
